"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import api from "@/lib/axios";
import Link from "next/link";
import { Plus, Search, Loader2, Pencil, Trash2, ShoppingBag } from "lucide-react";
import { toast } from "sonner";

interface Product {
    _id: string;
    title: string;
    shortDescription: string;
    category: string;
    image: string;
    marketPrice: number;
    offerPrice: number;
    vendorApproved: boolean;
    createdAt: string;
}

export default function ProductsPage() {
    const router = useRouter();
    const [products, setProducts] = useState<Product[]>([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [deletingId, setDeletingId] = useState<string | null>(null);

    const fetchProducts = async () => {
        try {
            setLoading(true);
            const params: Record<string, string> = {};
            if (search) params.search = search;
            const res = await api.get("/vendor/products", { params });
            setProducts(res.data.products || []);
        } catch {
            toast.error("Failed to load products");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => { fetchProducts(); }, []);

    useEffect(() => {
        const timer = setTimeout(() => fetchProducts(), 300);
        return () => clearTimeout(timer);
    }, [search]);

    const handleDelete = async (id: string) => {
        if (!confirm("Are you sure you want to delete this product?")) return;
        try {
            setDeletingId(id);
            await api.delete(`/vendor/products/${id}`);
            toast.success("Product deleted");
            fetchProducts();
        } catch {
            toast.error("Failed to delete product");
        } finally {
            setDeletingId(null);
        }
    };

    return (
        <div className="space-y-6 pb-8">
            <div className="sticky top-0 z-20 bg-background/95 backdrop-blur border-b border-border -mx-6 px-6 py-4 mb-6">
                <div className="flex items-center justify-between">
                    <div>
                        <div className="flex items-center gap-2 text-xs text-muted-foreground mb-0.5">
                            <span>Dashboard</span><span>/</span>
                            <span className="text-[#8D0303] font-medium">Products</span>
                        </div>
                        <h1 className="text-xl font-bold">My Products</h1>
                    </div>
                    <Link href="/dashboard/products/new">
                        <Button size="sm" className="bg-[#8D0303] hover:bg-[#700202] text-white">
                            <Plus className="w-4 h-4 mr-1.5" /> Add Product
                        </Button>
                    </Link>
                </div>
            </div>

            <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <Input placeholder="Search products..." value={search} onChange={(e) => setSearch(e.target.value)} className="pl-9 h-10" />
            </div>

            {loading ? (
                <div className="flex items-center justify-center h-48">
                    <Loader2 className="w-8 h-8 animate-spin text-[#8D0303]" />
                </div>
            ) : products.length === 0 ? (
                <div className="text-center py-16 bg-muted/20 rounded-xl border border-dashed border-border">
                    <ShoppingBag className="w-12 h-12 text-muted-foreground mx-auto mb-3 opacity-40" />
                    <h3 className="font-bold text-lg mb-1">No products yet</h3>
                    <p className="text-muted-foreground text-sm mb-4">Add your first product to start selling.</p>
                    <Link href="/dashboard/products/new">
                        <Button size="sm" className="bg-[#8D0303] hover:bg-[#700202] text-white">
                            <Plus className="w-4 h-4 mr-1.5" /> Add Product
                        </Button>
                    </Link>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                    {products.map((product) => (
                        <Card key={product._id} className="border shadow-sm hover:shadow-md transition-shadow">
                            <CardContent className="p-4">
                                <div className="flex items-start justify-between mb-3">
                                    <div className="flex-1 min-w-0">
                                        <h3 className="font-bold text-base truncate">{product.title}</h3>
                                        <p className="text-xs text-muted-foreground capitalize">{product.category}</p>
                                    </div>
                                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ml-2 shrink-0 ${product.vendorApproved ? "bg-green-100 text-green-800" : "bg-yellow-100 text-yellow-800"}`}>
                                        {product.vendorApproved ? "Approved" : "Pending"}
                                    </span>
                                </div>
                                {product.shortDescription && (
                                    <p className="text-xs text-muted-foreground mb-3 line-clamp-2">{product.shortDescription}</p>
                                )}
                                <div className="flex items-center gap-2 mb-3">
                                    {product.marketPrice > 0 && (
                                        <span className="text-xs text-muted-foreground line-through">₹{product.marketPrice}</span>
                                    )}
                                    <span className="text-lg font-black">₹{product.offerPrice || product.marketPrice || 0}</span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <Button size="sm" variant="outline" className="flex-1" onClick={() => router.push(`/dashboard/products/edit/${product._id}`)}>
                                        <Pencil className="w-3 h-3 mr-1" /> Edit
                                    </Button>
                                    <Button size="sm" variant="outline" className="text-red-600 hover:bg-red-50" onClick={() => handleDelete(product._id)} disabled={deletingId === product._id}>
                                        {deletingId === product._id ? <Loader2 className="w-3 h-3 animate-spin" /> : <Trash2 className="w-3 h-3" />}
                                    </Button>
                                </div>
                            </CardContent>
                        </Card>
                    ))}
                </div>
            )}
        </div>
    );
}
